    88	/**
    89	 * Narrow child-process surface for launcher-failure cleanup. It deliberately
    90	 * carries no PGID: before the worker has published a verified process identity,
    91	 * descriptor-delivery failure may only target the direct child.
    92	 */
    93	export interface ManagedHostRunLaunchedWorkerHandle {
    94	  pid?: number;
    95	  exitCode: number | null;
    96	  signalCode: NodeJS.Signals | null;
    97	  kill(signal?: NodeJS.Signals | number): boolean;
    98	  once(event: 'close' | 'error', listener: () => void): unknown;
    99	}
   100	
   101	/**
   102	 * Best-effort direct-child cleanup before a worker has returned a durable,
   103	 * fingerprint-bound process identity. Do not infer that `pid` is an isolated
   104	 * process group: a negative-PGID signal here could target a recycled or
   105	 * unrelated group. The launch failure remains replacement-unsafe at the
   106	 * submitter boundary even if this direct-child reap appears to succeed.
   107	 */
   108	export async function reapUnidentifiedManagedHostRunWorker(
   109	  child: ManagedHostRunLaunchedWorkerHandle,
   110	  wait: (ms: number) => Promise<void> = sleep,
   111	): Promise<{ directKillSent: boolean; reaped: boolean }> {
   112	  let directKillSent = false;
   113	  if (child.pid && child.pid > 1) {
   114	    try {
   115	      directKillSent = child.kill('SIGKILL') !== false;
   116	    } catch {
   117	      // The child may already have exited; retain a replacement-unsafe launch failure.
   118	    }
   119	  }
   120	  let reaped = child.exitCode !== null || child.signalCode !== null;
   121	  if (!reaped) {
   122	    await Promise.race([
   123	      new Promise<void>(resolveClose => {
   124	        child.once('close', resolveClose);
   125	        child.once('error', resolveClose);
   126	      }),
   127	      wait(1_000),
   128	    ]);
   129	    reaped = child.exitCode !== null || child.signalCode !== null;
   130	  }
   131	  return { directKillSent, reaped };
   132	}
